INSERT INTO audit_rules (id, category, severity, title, description, recommendation, documentation_url, weight)
VALUES
('indexability.http.client_error', 'indexability', 'high', 'Page returns a 4xx client error', 'Internally linked URLs that return 4xx (404, 410, 403…) waste crawl budget and break the user journey. Linked 404s also leak link equity.', 'Fix or remove internal links pointing here. If the page moved, 301-redirect it to the closest equivalent; if it is intentionally gone, return 410 and drop the links.', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors', 3),
('indexability.http.server_error', 'indexability', 'critical', 'Page returns a 5xx server error', 'Server errors prevent crawling and indexing entirely. Repeated 5xx responses cause Google to reduce crawl rate and eventually drop the URL.', 'Inspect server logs for this URL, fix the underlying failure (timeouts, exceptions, upstream outages) and re-crawl to confirm a 200.', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors', 3),
('indexability.http.unreachable', 'indexability', 'high', 'Page could not be fetched (timeout / network error)', 'The crawler could not obtain a response within the time budget. Search engine crawlers apply similar limits and will treat the URL as unavailable.', 'Check server capacity, DNS and TLS configuration for this URL. If it is consistently slow, look at server-side rendering time and upstream dependencies.', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors', 2),
('indexability.http.blocked', 'indexability', 'medium', 'Crawler blocked (403 / bot challenge)', 'The server refused the request or served a bot-protection challenge. If Googlebot is treated the same way the page will not be indexed.', 'Verify that your WAF/CDN allows verified search engine crawlers and the SEOPilot user agent. Test with the URL Inspection tool in Search Console.', 'https://developers.google.com/search/docs/crawling-indexing/verifying-googlebot', 1),
('indexability.robots.noindex_in_sitemap', 'indexability', 'high', 'Noindex page listed in XML sitemap', 'Sitemaps should only contain canonical, indexable URLs. Listing noindex pages sends contradictory signals and wastes crawl budget.', 'Either remove the URL from the sitemap or remove the noindex directive, depending on whether the page should rank.', 'https://developers.google.com/search/docs/crawling-indexing/sitemaps/build-sitemap', 2),
('indexability.robots.noindex', 'indexability', 'notice', 'Page is noindex', 'Informational: this page asks search engines not to index it. Review the list to make sure no revenue-generating pages are excluded by mistake.', 'Confirm each noindexed page is intentional (thank-you pages, internal search, filters). Remove the directive from pages that should rank.', 'https://developers.google.com/search/docs/crawling-indexing/block-indexing', 1),
('indexability.robots.blocked_by_robots_txt', 'indexability', 'notice', 'URL disallowed by robots.txt', 'Informational: internally linked URLs that robots.txt disallows. Blocked URLs can still be indexed (without content) if linked, and cannot pass a noindex.', 'Make sure disallowed paths are not meant to rank. To keep a page out of the index, use noindex instead of robots.txt.', 'https://developers.google.com/search/docs/crawling-indexing/robots/intro', 1),
('indexability.canonical.missing', 'indexability', 'low', 'Missing canonical tag', 'Without a canonical, search engines choose the canonical themselves, which can split signals between URL variants (parameters, trailing slashes, http/https).', 'Add a self-referencing <link rel="canonical"> with the absolute preferred URL on every indexable page.', 'https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls', 1),
('indexability.canonical.points_elsewhere', 'indexability', 'notice', 'Canonical points to a different URL', 'Informational: the page declares another URL as canonical, so it will not be indexed itself. Check that this is intended and that the target is indexable.', 'For unique content, use a self-referencing canonical. Verify the canonical target returns 200, is indexable and is not itself canonicalised elsewhere.', 'https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls', 1),
('indexability.canonical.target_broken', 'indexability', 'high', 'Canonical target is not a 200 indexable page', 'A canonical that points to a redirect, error or noindex page is ignored by search engines and creates an indexing dead end.', 'Point the canonical at the final 200, indexable URL (follow any redirect chain to its end).', 'https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls', 3),
('indexability.canonical.conflict', 'indexability', 'medium', 'Conflicting canonical signals (HTML vs HTTP header)', 'The page sends a canonical both in HTML and in a Link HTTP header and they disagree; search engines may pick either.', 'Use only one canonical declaration per page, or make sure both refer to the same absolute URL.', 'https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls', 2),
('indexability.redirect.chain', 'indexability', 'medium', 'Redirect chain', 'Multiple consecutive redirects slow users down and each hop loses a little crawl budget; Googlebot follows at most 10 hops.', 'Update the internal links to point at the final URL and collapse the chain to a single 301.', 'https://developers.google.com/search/docs/crawling-indexing/301-redirects', 2),
('indexability.redirect.loop', 'indexability', 'critical', 'Redirect loop', 'The URL redirects back to itself (directly or via other URLs). Browsers and crawlers give up, so the content is unreachable.', 'Fix the redirect rules so the chain terminates at a 200 page.', 'https://developers.google.com/search/docs/crawling-indexing/301-redirects', 2),
('indexability.redirect.temporary', 'indexability', 'low', 'Temporary redirect (302/307) used for a permanent move', '302/307 tells search engines the original URL may return, so signals are consolidated more slowly than with a 301/308.', 'If the move is permanent, use a 301 (or 308 to preserve method).', 'https://developers.google.com/search/docs/crawling-indexing/301-redirects', 1),
('indexability.redirect.meta_refresh', 'indexability', 'low', 'Redirect target is a 4xx/5xx', 'Redirects that end on an error page send users and crawlers to a dead end.', 'Repoint the redirect to a live 200 page or remove it.', 'https://developers.google.com/search/docs/crawling-indexing/301-redirects', 1),
('indexability.sitemap.missing', 'indexability', 'medium', 'No XML sitemap found', 'No sitemap was declared in robots.txt or found at /sitemap.xml. Sitemaps help search engines discover deep and recently changed pages.', 'Generate an XML sitemap containing canonical indexable URLs with accurate <lastmod>, reference it in robots.txt and submit it in Search Console.', 'https://developers.google.com/search/docs/crawling-indexing/sitemaps/overview', 2),
('indexability.sitemap.non_200_urls', 'indexability', 'medium', 'Sitemap lists a URL that is not a 200', 'Sitemap URLs that redirect or error erode trust in the sitemap and waste crawl budget.', 'Regenerate the sitemap from the live canonical URL set and drop redirected/removed entries.', 'https://developers.google.com/search/docs/crawling-indexing/sitemaps/build-sitemap', 2),
('indexability.sitemap.orphan_only_in_sitemap', 'indexability', 'low', 'Orphan page (only reachable via sitemap)', 'The page has no internal links pointing to it. Pages without internal links receive little PageRank and are seen as unimportant.', 'Link to the page from relevant navigation, hub or related-content sections, or remove it from the sitemap if it should not rank.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('indexability.sitemap.indexable_not_in_sitemap', 'indexability', 'notice', 'Indexable page missing from XML sitemap', 'Informational: indexable pages not listed in any sitemap. Not an error, but sitemap coverage helps discovery and lets Search Console report on the page.', 'Include all canonical indexable URLs in the sitemap.', 'https://developers.google.com/search/docs/crawling-indexing/sitemaps/build-sitemap', 1),
('indexability.robots_txt.missing', 'indexability', 'low', 'robots.txt not found', 'A missing robots.txt is treated as ''allow all'', which is fine, but you lose the ability to declare sitemaps and steer crawlers away from low-value URLs.', 'Add a robots.txt at the site root with at least a Sitemap: line.', 'https://developers.google.com/search/docs/crawling-indexing/robots/create-robots-txt', 1),
('indexability.robots_txt.blocks_all', 'indexability', 'critical', 'robots.txt disallows the whole site', 'A `Disallow: /` for all user agents prevents search engines from crawling any page.', 'Remove the blanket disallow (often left over from staging) and re-submit the sitemap.', 'https://developers.google.com/search/docs/crawling-indexing/robots/intro', 3),
('indexability.homepage.not_indexable', 'indexability', 'critical', 'Homepage is not indexable', 'The start URL does not return a 200 indexable HTML document. Nothing else matters until this is fixed.', 'Ensure the homepage returns 200, has no noindex, and its canonical points to itself.', 'https://developers.google.com/search/docs/crawling-indexing/block-indexing', 3),
('indexability.url.uppercase_or_spaces', 'indexability', 'notice', 'URL contains uppercase letters or encoded spaces', 'Mixed-case paths create duplicate URL variants on case-sensitive servers; encoded spaces are hard to share and read.', 'Use lowercase, hyphen-separated URL paths and redirect other variants.', 'https://developers.google.com/search/docs/crawling-indexing/url-structure', 1),
('indexability.url.too_long', 'indexability', 'notice', 'URL is very long', 'URLs over ~115 characters are truncated in SERPs and often signal parameter bloat.', 'Prefer short descriptive slugs and avoid unnecessary query parameters.', 'https://developers.google.com/search/docs/crawling-indexing/url-structure', 1),
('metadata.title.missing', 'metadata', 'high', 'Missing <title>', 'The title is the strongest on-page relevance signal and the headline of the search result. Without it Google generates one from page content or anchors.', 'Add a unique, descriptive <title> of roughly 30–60 characters that includes the primary topic and, optionally, the brand.', 'https://developers.google.com/search/docs/appearance/title-link', 3),
('metadata.title.too_long', 'metadata', 'low', 'Title longer than 60 characters', 'Long titles are truncated in search results and Google is more likely to rewrite them.', 'Trim to about 60 characters, front-loading the most important words.', 'https://developers.google.com/search/docs/appearance/title-link', 1),
('metadata.title.too_short', 'metadata', 'low', 'Title shorter than 30 characters', 'Very short titles rarely describe the page well enough to earn clicks or cover secondary terms.', 'Expand the title to 30–60 characters with a specific description of the page.', 'https://developers.google.com/search/docs/appearance/title-link', 1),
('metadata.title.duplicate', 'metadata', 'medium', 'Duplicate title across pages', 'Several indexable pages share the same title, which makes it hard for search engines (and users) to tell them apart and hints at duplicate content.', 'Write a unique title for each page that reflects its specific content.', 'https://developers.google.com/search/docs/appearance/title-link', 2),
('metadata.title.same_as_h1', 'metadata', 'notice', 'Title identical to H1', 'Informational: using the exact same text for title and H1 wastes an opportunity to target a secondary phrasing.', 'Keep them aligned in topic but vary the wording (e.g. add a benefit or qualifier to the title).', 'https://developers.google.com/search/docs/appearance/title-link', 1),
('metadata.description.missing', 'metadata', 'medium', 'Missing meta description', 'Meta descriptions are not a ranking factor, but they are the default snippet and directly affect click-through rate.', 'Write a compelling 70–160 character summary with a call to action and the main keyword.', 'https://developers.google.com/search/docs/appearance/snippet', 2),
('metadata.description.too_long', 'metadata', 'notice', 'Meta description longer than 160 characters', 'Long descriptions are truncated with an ellipsis in most results.', 'Trim to about 160 characters.', 'https://developers.google.com/search/docs/appearance/snippet', 1),
('metadata.description.too_short', 'metadata', 'notice', 'Meta description shorter than 70 characters', 'Very short descriptions leave snippet space unused and are often replaced by Google.', 'Expand to 70–160 characters.', 'https://developers.google.com/search/docs/appearance/snippet', 1),
('metadata.description.duplicate', 'metadata', 'low', 'Duplicate meta description across pages', 'Identical descriptions on different pages usually mean a template default is being used, producing undifferentiated snippets.', 'Write page-specific descriptions or omit the tag so Google builds a snippet from content.', 'https://developers.google.com/search/docs/appearance/snippet', 1),
('metadata.opengraph.missing', 'metadata', 'low', 'Missing Open Graph tags', 'Without og:title / og:description / og:image, links shared on social networks and chat apps render without a preview.', 'Add og:title, og:description and a 1200×630 og:image to every shareable page.', 'https://ogp.me/', 1),
('metadata.lang.missing', 'metadata', 'low', 'Missing <html lang> attribute', 'The lang attribute helps screen readers, translation tools and search engines identify the page language.', 'Set <html lang="xx"> to the page''s primary language using a BCP-47 code.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/lang', 1),
('content.h1.missing', 'content', 'medium', 'Missing H1', 'The H1 tells users and search engines what the page is about and anchors the heading outline.', 'Add exactly one H1 that describes the page''s main topic.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 2),
('content.h1.multiple', 'content', 'low', 'Multiple H1 tags', 'Several H1s dilute the main topic signal and usually indicate template misuse (logo, navigation or widgets marked up as H1).', 'Keep one H1 for the page title and demote the others to H2/H3 or plain styled text.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('content.headings.skipped_level', 'content', 'notice', 'Heading levels skipped', 'Jumping from H1 to H3 (etc.) breaks the document outline used by assistive technology and content-understanding systems.', 'Nest headings sequentially (H1 → H2 → H3) and use CSS for visual sizing instead of picking a level for its look.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Element/Heading_Elements', 1),
('content.thin', 'content', 'medium', 'Thin content', 'Indexable pages with fewer than 200 words of body text rarely satisfy a query on their own and can drag down site-wide quality assessments.', 'Expand the page with genuinely useful content, merge it into a stronger page, or noindex it if it serves a non-search purpose.', 'https://developers.google.com/search/docs/fundamentals/creating-helpful-content', 2),
('content.duplicate', 'content', 'high', 'Duplicate content (identical body text)', 'Two or more indexable pages have identical main content and no canonical relationship. Search engines will pick one and may ignore the rest.', 'Consolidate with a canonical or 301 to the preferred URL, or differentiate the content.', 'https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls', 3),
('content.empty_shell', 'content', 'high', 'Page has almost no HTML content (likely client-side rendered)', 'The raw HTML contains fewer than 20 words. If content only appears after JavaScript runs, indexing is delayed and some crawlers will see an empty page.', 'Server-side render or pre-render the primary content, or enable JavaScript rendering in the crawl settings to verify what the rendered DOM contains.', 'https://developers.google.com/search/docs/crawling-indexing/javascript-seo-basics', 2),
('content.lorem_or_placeholder', 'content', 'medium', 'Placeholder text detected in title or headings', 'Text such as ''lorem ipsum'', ''untitled'' or ''coming soon'' in the title/H1 indicates an unfinished page that should not be indexed.', 'Finish the page content or noindex it until it is ready.', 'https://developers.google.com/search/docs/fundamentals/creating-helpful-content', 1),
('links.internal.broken', 'links', 'high', 'Broken internal link', 'The page links to an internal URL that returns 4xx/5xx. Users hit dead ends and PageRank is wasted.', 'Update the link to the correct URL or remove it. Where the target moved, add a 301.', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors', 3),
('links.external.broken', 'links', 'low', 'Broken external link', 'The page links to an external URL that returned 4xx/5xx when checked. Dead outbound links hurt user trust and page quality signals.', 'Replace the link with a live source (check the Wayback Machine for an equivalent) or remove it.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('links.internal.to_redirect', 'links', 'low', 'Internal link points to a redirect', 'Linking to URLs that redirect adds latency for users and an extra hop for crawlers on every visit.', 'Update internal links to point directly at the final destination URL.', 'https://developers.google.com/search/docs/crawling-indexing/301-redirects', 1),
('links.internal.nofollow', 'links', 'low', 'Internal link uses rel=nofollow', 'Nofollow on internal links throws away PageRank you already own; it does not conserve it.', 'Remove rel=nofollow from internal links. To keep a page out of the index, use noindex on that page.', 'https://developers.google.com/search/docs/crawling-indexing/qualify-outbound-links', 1),
('links.page.orphan', 'links', 'medium', 'Page has no internal inbound links', 'No crawled page links to this URL (it was found via sitemap, canonical or hreflang only). Search engines treat unlinked pages as low priority.', 'Link to the page from navigation, hubs or contextually related pages.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 2),
('links.page.only_nofollow_inbound', 'links', 'low', 'Page only reachable through nofollow links', 'All internal links to this page are nofollow, so it receives no internal PageRank.', 'Add at least one followed internal link from a relevant page.', 'https://developers.google.com/search/docs/crawling-indexing/qualify-outbound-links', 1),
('links.page.deep', 'links', 'low', 'Page is more than 4 clicks from the homepage', 'Click depth is a strong proxy for importance. Deep pages are crawled less often and rank worse.', 'Flatten the architecture: add hub pages, related links, pagination shortcuts or breadcrumb links so important pages sit within 3 clicks.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('links.page.too_many', 'links', 'notice', 'More than 300 links on the page', 'Very large link counts dilute the value passed per link and often indicate mega-menus or tag clouds that crawlers must process on every page.', 'Reduce boilerplate links; keep navigation focused and move exhaustive lists to dedicated index pages.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('links.anchor.generic', 'links', 'notice', 'Generic anchor text on internal links', 'Anchors like ''click here'' or ''read more'' give search engines no information about the target page.', 'Use descriptive anchor text that names the topic of the destination page.', 'https://developers.google.com/search/docs/fundamentals/seo-starter-guide', 1),
('links.external.http_on_https_site', 'links', 'notice', 'Internal link uses http:// on an https site', 'Links to the http:// version of your own site force a redirect on every click and can leak referrer data.', 'Update internal links to https:// (search the templates and database for the old scheme).', 'https://developers.google.com/search/docs/crawling-indexing/https-best-practices', 1),
('performance.ttfb.slow', 'performance', 'medium', 'Slow server response (TTFB > 800 ms)', 'Time to first byte measured from the crawler. Google recommends keeping server response under 800 ms; slow TTFB delays every other metric (LCP, FCP).', 'Add caching (CDN / full-page cache), optimise database queries and reduce server-side work on the critical path. Measure with the PageSpeed integration for field data.', 'https://web.dev/articles/ttfb', 2),
('performance.response.slow', 'performance', 'low', 'Slow HTML download (> 3000 ms)', 'Total time to receive the HTML document. Long downloads usually mean an oversized document or slow origin.', 'Enable compression, reduce inline scripts/styles and trim server-rendered markup.', 'https://web.dev/articles/ttfb', 1),
('performance.html.large', 'performance', 'low', 'HTML document larger than 300 KB', 'Very large HTML delays parsing and rendering and often contains inlined data or CSS that should be external and cacheable.', 'Move large inline JSON/CSS to external cached files, paginate long lists and remove hidden markup.', 'https://web.dev/articles/optimize-lcp', 1),
('performance.compression.missing', 'performance', 'medium', 'HTML served without compression', 'The response was not gzip/br compressed although the crawler advertised support. Compression typically cuts HTML size by 70–80%.', 'Enable Brotli or gzip for text/html at the web server or CDN.', 'https://web.dev/articles/reduce-network-payloads-using-text-compression', 2),
('performance.cache_control.missing', 'performance', 'notice', 'No Cache-Control header on HTML', 'Without explicit caching directives intermediaries and browsers guess, which can mean either stale pages or no caching at all.', 'Send an explicit Cache-Control (e.g. `public, max-age=0, s-maxage=600, stale-while-revalidate=86400` for CDN-cached HTML).', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control', 1),
('security.https.not_used', 'security', 'critical', 'Page served over HTTP', 'HTTPS is a ranking signal and browsers mark HTTP pages as ''Not secure''. Everything sent between user and site is readable in transit.', 'Install a TLS certificate, redirect all HTTP URLs to HTTPS with a 301 and update internal links and canonicals.', 'https://developers.google.com/search/docs/crawling-indexing/https-best-practices', 3),
('security.https.no_redirect_from_http', 'security', 'high', 'HTTP version of the homepage does not redirect to HTTPS', 'The crawl started from or discovered an http:// homepage that serves content instead of redirecting, creating a duplicate insecure site.', 'Add a server-level 301 from http:// to https:// for every URL.', 'https://developers.google.com/search/docs/crawling-indexing/https-best-practices', 2),
('security.mixed_content', 'security', 'high', 'Mixed content (HTTP resources on an HTTPS page)', 'Scripts, styles or images loaded over HTTP on an HTTPS page are blocked or flagged by browsers, breaking functionality and the padlock.', 'Load every sub-resource over HTTPS (protocol-relative or absolute https URLs) and add `Content-Security-Policy: upgrade-insecure-requests` as a safety net.', 'https://web.dev/articles/what-is-mixed-content', 2),
('security.headers.hsts_missing', 'security', 'low', 'Missing Strict-Transport-Security header', 'HSTS tells browsers to always use HTTPS for your domain, preventing downgrade attacks and the initial insecure request.', 'Send `Strict-Transport-Security: max-age=31536000; includeSubDomains` once all subdomains support HTTPS.', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Strict-Transport-Security', 1),
('security.headers.content_type_options_missing', 'security', 'notice', 'Missing X-Content-Type-Options: nosniff', 'Without nosniff, browsers may MIME-sniff responses and execute content as script.', 'Send `X-Content-Type-Options: nosniff` on all responses.', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/X-Content-Type-Options', 1),
('security.headers.frame_protection_missing', 'security', 'notice', 'No clickjacking protection (X-Frame-Options / CSP frame-ancestors)', 'Pages that can be framed by any origin are vulnerable to clickjacking.', 'Send `Content-Security-Policy: frame-ancestors ''self''` (preferred) or `X-Frame-Options: SAMEORIGIN`.', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/X-Frame-Options', 1),
('security.headers.server_version_exposed', 'security', 'notice', 'Server software version exposed in headers', 'Server or X-Powered-By headers reveal exact software versions that make targeted attacks easier.', 'Configure the web server/framework to omit version details (e.g. `server_tokens off`, remove X-Powered-By).', 'https://owasp.org/www-project-secure-headers/', 1),
('mobile.viewport.missing', 'mobile', 'high', 'Missing viewport meta tag', 'Without a viewport meta tag mobile browsers render the page at desktop width, producing tiny text and horizontal scrolling. Google indexes the mobile version first.', 'Add `<meta name="viewport" content="width=device-width, initial-scale=1">` to the <head>.', 'https://developers.google.com/search/docs/crawling-indexing/mobile/mobile-sites-mobile-first-indexing', 3),
('structured_data.invalid', 'structured_data', 'medium', 'Structured data has errors', 'JSON-LD that fails to parse or lacks properties Google requires makes the page ineligible for rich results.', 'Fix the listed errors and re-validate with Google''s Rich Results Test.', 'https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data', 2),
('structured_data.missing_recommended', 'structured_data', 'notice', 'Structured data missing recommended properties', 'Recommended properties are not required, but adding them increases the chance and richness of enhanced results.', 'Add the listed recommended properties where the data exists.', 'https://developers.google.com/search/docs/appearance/structured-data/search-gallery', 1),
('structured_data.none_on_site', 'structured_data', 'low', 'No structured data found anywhere on the site', 'Not a single crawled page declares schema.org markup. Structured data enables rich results and helps AI/answer engines understand entities.', 'Start with Organization/WebSite on the homepage, BreadcrumbList site-wide and content-specific types (Article, Product, FAQPage…) where applicable.', 'https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data', 1),
('structured_data.homepage_missing_organization', 'structured_data', 'notice', 'Homepage lacks Organization / WebSite schema', 'Organization (or LocalBusiness/Person) and WebSite markup on the homepage establish the site entity for knowledge panels and AI answers.', 'Add JSON-LD Organization (name, url, logo, sameAs) and WebSite to the homepage.', 'https://developers.google.com/search/docs/appearance/structured-data/organization', 1),
('images.alt.missing', 'images', 'medium', 'Images missing alt text', 'Alt text is required for accessibility and is the main signal for image search. Decorative images should use an empty alt (alt="").', 'Add descriptive alt text to content images; use alt="" for purely decorative ones.', 'https://developers.google.com/search/docs/appearance/google-images', 2),
('images.og_image.missing', 'images', 'notice', 'No og:image', 'Shared links without an image get far less engagement on social and messaging platforms.', 'Provide a 1200×630 og:image (absolute URL) on every page intended to be shared.', 'https://ogp.me/#structured', 1),
('international.hreflang.invalid_code', 'international', 'medium', 'Invalid hreflang language/region code', 'hreflang values must be ISO 639-1 language codes optionally followed by an ISO 3166-1 Alpha-2 region (e.g. en, en-GB, x-default). Invalid values are ignored.', 'Correct the codes (common mistakes: en-UK → en-GB, using country only, underscores instead of hyphens).', 'https://developers.google.com/search/docs/specialty/international/localized-versions', 2),
('international.hreflang.missing_self', 'international', 'low', 'hreflang set does not include the page itself', 'Each page in an hreflang cluster must list itself; otherwise the annotations are ignored.', 'Add a self-referencing hreflang entry with the page''s own language.', 'https://developers.google.com/search/docs/specialty/international/localized-versions', 1),
('international.hreflang.no_return_link', 'international', 'medium', 'hreflang target does not link back', 'hreflang must be reciprocal: if A lists B, B must list A. One-directional annotations are discarded.', 'Add the missing return annotations on the target pages (or generate hreflang from a single source of truth / sitemap).', 'https://developers.google.com/search/docs/specialty/international/localized-versions', 2),
('international.hreflang.missing_x_default', 'international', 'notice', 'hreflang cluster has no x-default', 'x-default tells search engines which version to show users whose language does not match any listed variant.', 'Add `<link rel="alternate" hreflang="x-default" href="…">` pointing to the language selector or default version.', 'https://developers.google.com/search/docs/specialty/international/localized-versions', 1),
('international.hreflang.target_not_indexable', 'international', 'medium', 'hreflang points to a non-200 or noindex page', 'Alternate URLs must be live, indexable pages; pointing at redirects or errors invalidates the cluster.', 'Update hreflang targets to the final canonical, indexable URLs.', 'https://developers.google.com/search/docs/specialty/international/localized-versions', 1)
